  <script>
    // Brief intake => summary builder
    function makeVisitSummary(){
      const name=document.getElementById('name').value.trim() || '(name)';
      const contact=document.getElementById('contact').value.trim() || '(contact)';
      const focus=document.getElementById('focus').value;
      const when=document.getElementById('when').value;
      const len=document.getElementById('len').value;
      const practical=document.getElementById('practical').value.trim();
      const brief=document.getElementById('brief').value.trim();

      const lines=[];
      lines.push('{{BUSINESS_NAME}} — Intake summary');
      lines.push('Name: '+name);
      lines.push('Contact: '+contact);
      lines.push('Focus: '+focus);
      lines.push('When noticed: '+when);
      lines.push('Preferred session length: '+len+' min');
      if(practical) lines.push('Practical notes: '+practical);
      if(brief) lines.push('\nPersonal note: '+brief);
      lines.push('\nQuestions I want to ask:');
      lines.push('- What would you recommend as next steps?');
      lines.push('- How do you suggest we measure progress early on?');
      lines.push('- How might we handle scheduling and contact between sessions?');
      lines.push('\nContact: {{EMAIL}} | {{PHONE}}');
      return lines.join('\n');
    }

    document.getElementById('toSummary').addEventListener('click',function(e){
      e.preventDefault(); document.getElementById('visitSummary').textContent=makeVisitSummary();
    });

    document.getElementById('copySummary').addEventListener('click',function(){
      const txt=document.getElementById('visitSummary').textContent || makeVisitSummary();
      navigator.clipboard && navigator.clipboard.writeText(txt).then(()=>{const o=this.textContent; this.textContent='Copied'; setTimeout(()=>this.textContent=o,1200)},()=>alert('Could not copy'));
    });

    // Simulate sending a booking request (local only)
    document.getElementById('send').addEventListener('click',function(e){
      e.preventDefault();
      const name=document.getElementById('name').value.trim();
      const contact=document.getElementById('contact').value.trim();
      if(!name || !contact){document.getElementById('result').textContent='Please provide your name and a contact method.'; return}
      document.getElementById('result').textContent='Request sent. I will follow up to schedule a time. Thank you.';
      // In a real site this would POST to a server; here we just simulate.
    });
  </script>
